<?php require_once __DIR__.'/../includes/bootstrap.php';require_role('Student');$q=db()->prepare('SELECT s.code,s.name,s.credits,s.subject_type,u.name faculty_name FROM student_subjects ss JOIN subjects s ON s.id=ss.subject_id LEFT JOIN faculty_subjects fs ON fs.subject_id=s.id LEFT JOIN faculty f ON f.id=fs.faculty_id LEFT JOIN users u ON u.id=f.user_id JOIN students st ON st.id=ss.student_id WHERE st.user_id=? ORDER BY s.code');$q->execute([actor_id()]);page_top('Academic Profile');?><div class='card p-3 table-responsive'><table class='table'><tr><th>Code</th><th>Subject</th><th>Credits</th><th>Type</th><th>Faculty</th></tr><?php foreach($q as $r):?><tr><td><?=e($r['code'])?></td><td><?=e($r['name'])?></td><td><?=e($r['credits'])?></td><td><?=e($r['subject_type'])?></td><td><?=e($r['faculty_name']??'—')?></td></tr><?php endforeach;?></table></div><?php page_bottom(); ?>